<?php
// File: public/index.php
// Map:
// - All pages are static HTML generated by the site build (apps/site → public/); Herd serves them directly.
//   This file only exists so Herd serves the public/ folder (https://omniaui.test) and handles misses.
// - "/" → contents of /index.html (status 200).
// - Clean URLs: "/ui/pro" serves ui/pro.html (links have no .html, scripts/clean-urls.mjs).
// - Old CSS docs URLs ("/docs/*", "/pages/*"): 301 redirect to the OmniaCSS site
//   (same base URL as OMNIACSS_URL in apps/site/src/lib/site.mjs).
// - Anything else: 404.

declare(strict_types=1);

$requestPath = parse_url($_SERVER["REQUEST_URI"] ?? "/", PHP_URL_PATH) ?? "/";
$normalizedPath = "/" . ltrim($requestPath, "/");

if (str_contains($normalizedPath, "..")) {
    http_response_code(400);
    echo "Bad request";
    exit;
}

if ($normalizedPath === "/") {
    // Serve the home page directly (200) instead of a redirect.
    header("Content-Type: text/html; charset=UTF-8");
    readfile(__DIR__ . "/index.html");
    exit;
}

// Clean URLs (as on the live site, see scripts/clean-urls.mjs): "/docs/colors/palettes" serves palettes.html.
$page = __DIR__ . rtrim($normalizedPath, "/") . ".html";
// "/ui/components/" (a folder without index.html next to components.html): redirect to "/ui/components", as live.
if (str_ends_with($normalizedPath, "/") && is_file($page) && !is_file(__DIR__ . $normalizedPath . "index.html")) {
    header("Location: " . rtrim($normalizedPath, "/"), true, 301);
    exit;
}
if (!str_ends_with($normalizedPath, ".html") && is_file($page)) {
    header("Content-Type: text/html; charset=UTF-8");
    readfile($page);
    exit;
}

if (str_starts_with($normalizedPath, "/docs/") || str_starts_with($normalizedPath, "/pages/")) {
    header("Location: https://omniacss.test" . $normalizedPath, true, 301);
    exit;
}

http_response_code(404);
echo "Not Found";
